import { exclaim } from "../strings/index.mjs";

export function greeting(s) {
  return exclaim(s);
}

import test from "node:test";
import assert from "node:assert/strict";
import { greeting } from "../packages/app/index.mjs";

test("greeting", () => {
  assert.equal(greeting("hi"), "hi!");
});

test("greeting appends exclamation to empty string", () => {
  assert.equal(greeting(""), "!");
});
